import React, { useState } from "react";
import { useTheme } from "styled-components";
import { useHistory } from "react-router-dom";
import EmailFormModal from "./EmailFormModal";
import TypewriterText from "./TypewriterText";
import useVoiceEngine from "./useVoiceEngine";
import { GlobalLiquidGlassStyles } from "./siriTheme";
import {
  VoiceContainer,
  VoiceAvatar,
  VoiceWaves,
  VoiceButton,
  TranscriptPanel,
  NoticeCard,
  VoiceStatus,
  VoiceControls,
  ButtonRow,
  ButtonLabel,
  ConnectionIndicator,
  CloseButton,
  HelpHint,
  TextInputRow,
  TextInputField,
  TextSendButton,
  FollowUpRow,
  FollowUpChip,
  TranscriptTools,
  TranscriptToolButton,
  EnableMicButton,
  SettingsButton,
  SettingsMenu,
  AnswerLink,
  PanelBody,
} from "./Siri.styles";
import {
  ButtonIcon,
  AvatarGlyph,
  MicrophoneIcon,
  ThinkingIcon,
  SpeakingIcon,
  ChatBubbleIcon,
  EmailIcon,
  SparkleIcon,
  IconText,
} from "./SiriIcons";
export { HeroTintSampler, PerformanceManager } from "./siriTheme";

// Global Styles with Enhanced Liquid Glass Design Tokens

// ============= ENHANCED VOICE ASSISTANT PANEL =============
// Presentation only — every behaviour lives in useVoiceEngine.
const VoiceAssistant = ({ onClose, theme: themeProp }) => {
  // Fall back to the app-level ThemeProvider. Callers have forgotten to pass
  // this prop before, which silently made every `theme?.name` check undefined
  // and pinned dependent UI (the email form) to dark.
  const themeFromContext = useTheme();
  const theme = themeProp || themeFromContext;

  const history = useHistory();

  const {
    answerLinks,
    assistantState,
    clearTranscript,
    closeChat,
    connectionStatus,
    copiedTranscript,
    copyTranscript,
    deviceInfo,
    emailInquiryType,
    emailTranscript,
    flatMode,
    followUps,
    handleEmailFormSubmit,
    hasPermission,
    interimTranscript,
    isAutoMode,
    isClosing,
    isFirstInteraction,
    isKeyboardOpen,
    isMetering,
    isVisible,
    motionReduce,
    notice,
    requestMicrophonePermission,
    scrollTranscriptToEnd,
    setShowEmailForm,
    setShowTextInput,
    setTextInput,
    showEmailForm,
    showHelp,
    showTextInput,
    speakIntroduction,
    startListening,
    stopAll,
    submitText,
    suggestionIndex,
    testTTS,
    textInput,
    textInputRef,
    toggleAutoMode,
    toggleFlatMode,
    transcriptEntries,
    transcriptRef,
    voiceIntensity,
    panelRef,
  } = useVoiceEngine({ onClose });

  const [showSettings, setShowSettings] = useState(false);

  // Tappable openers — they go through the typed path, so they work before
  // the microphone is enabled.
  const starterQuestions = [
    "Give me a quick overview of Laxman",
    "What has he built recently?",
    "I'd like to hire Laxman",
    "How can I contact him?",
  ];

  // ============= ENHANCED GET VOICE STATUS FUNCTION =============

  // Starter chips already show example questions, so the subtitle and the
  // bottom hint stop repeating them while the chips are up.
  const showStarters =
    transcriptEntries.length === 0 &&
    followUps.length === 0 &&
    assistantState === "idle";
  // Once a conversation is on screen the orb steps down a size, giving the
  // transcript more of the panel's fixed height.
  const compact =
    transcriptEntries.length > 0 ||
    !!interimTranscript ||
    assistantState === "thinking";

  const getVoiceStatus = () => {
    // Icon configuration
    const iconSize = deviceInfo.isMobile ? 20 : 24;
    const iconColor = "currentColor";

    // 💡 Enhanced Suggestions Array with Icons
    const suggestions = [
      {
        text: deviceInfo.isMobile
          ? 'Tap the orb and say "I want to hire Laxman"'
          : 'Click the orb and say "I want to hire Laxman"',
        icon: <ChatBubbleIcon size={iconSize} color={iconColor} animated />,
      },
      {
        text: 'Try "Give me a quick overview"',
        icon: <SparkleIcon size={iconSize} color={iconColor} />,
      },
      {
        text: 'Try "Send an email to Laxman"',
        icon: <EmailIcon size={iconSize} color={iconColor} />,
      },
      {
        text: deviceInfo.isMobile
          ? "Tap the orb to start talking"
          : "Click the orb to start talking",
        icon: <MicrophoneIcon size={iconSize} color={iconColor} animated />,
      },
    ];

    switch (assistantState) {
      case "listening":
        return {
          title: (
            <IconText
              icon={<MicrophoneIcon size={iconSize} color="#10b981" animated />}
              text="Listening…"
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "Go ahead"
            : "Go ahead — I'm listening",
        };

      case "thinking":
        return {
          title: (
            <IconText
              icon={<ThinkingIcon size={iconSize} color="#3b82f6" />}
              text="Thinking…"
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "Finding the answer"
            : "Finding the right answer",
        };

      case "speaking":
        return {
          title: (
            <IconText
              icon={<SpeakingIcon size={iconSize} color="#8b5cf6" />}
              text="Answering…"
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "Tap the orb to stop"
            : "Click the orb to stop",
        };

      default:
        return {
          title: "Ask Jarvis about Laxman",
          subtitle:
            connectionStatus === "connected" && showStarters ? (
              deviceInfo.isMobile ? (
                "Tap the orb to talk, or pick a question"
              ) : (
                "Click the orb to talk, or pick a question below"
              )
            ) : connectionStatus === "connected" ? (
              <IconText
                icon={suggestions[suggestionIndex]?.icon}
                text={suggestions[suggestionIndex]?.text}
              />
            ) : connectionStatus === "connecting" ? (
              <IconText
                icon={<ThinkingIcon size={iconSize - 4} color={iconColor} />}
                text="Setting up your microphone…"
              />
            ) : (
              "Talk or type — enable your microphone to use voice."
            ),
        };
    }
  };

  const statusText = getVoiceStatus();
  const isDisabled = connectionStatus !== "connected" || !hasPermission;

  // Single accessible name for the orb, doubling as the polite live-region
  // announcement — sighted users read the state from its colour.
  const avatarLabel = isDisabled
    ? "Enable microphone to start voice chat"
    : assistantState === "listening"
    ? "Listening — activate to stop"
    : assistantState === "thinking"
    ? "Thinking — activate to stop"
    : assistantState === "speaking"
    ? "Speaking — activate to stop"
    : "Start talking to Jarvis";

  if (!isVisible) return null;

  return (
    <>
      <GlobalLiquidGlassStyles />

      {/* Enhanced Notice */}
      {notice && (
        <NoticeCard
          type={notice.type}
          show={notice.show}
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          role="status"
          aria-live="polite"
        >
          <div className="notice-title">{notice.title}</div>
          <div className="notice-content">{notice.content}</div>
        </NoticeCard>
      )}
      {/* ✅ ADD EMAIL FORM MODAL */}
      <EmailFormModal
        show={showEmailForm}
        onClose={() => setShowEmailForm(false)}
        inquiryType={emailInquiryType}
        onSubmit={handleEmailFormSubmit}
        isMobile={deviceInfo.isMobile}
        // themeMode={theme.name === 'light' ? 'light' : 'dark'}
        themeMode={theme?.name === "light" ? "light" : "dark"}
      />

      {/* Enhanced Voice Assistant Container */}
      <VoiceContainer
        ref={panelRef}
        role="dialog"
        aria-label="Jarvis, Laxman's AI voice assistant"
        state={assistantState}
        isClosing={isClosing}
        isMobile={deviceInfo.isMobile}
        isKeyboardOpen={isKeyboardOpen}
        flatMode={flatMode}
        motionReduce={motionReduce}
      >
        <ConnectionIndicator
          status={connectionStatus}
          isMobile={deviceInfo.isMobile}
          motionReduce={motionReduce}
          flatMode={flatMode}
          aria-hidden="true"
        />

        <CloseButton
          onClick={closeChat}
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          type="button"
          aria-label="Close Jarvis"
        >
          <span aria-hidden="true">×</span>
        </CloseButton>

        {!deviceInfo.isMobile && (
          <SettingsButton
            onClick={() => setShowSettings((v) => !v)}
            isMobile={deviceInfo.isMobile}
            flatMode={flatMode}
            theme={theme}
            type="button"
            aria-label="Voice settings"
            aria-expanded={showSettings}
            title="Settings"
          >
            <span aria-hidden="true">⋯</span>
          </SettingsButton>
        )}

        {showSettings && !deviceInfo.isMobile && (
          <SettingsMenu isMobile={deviceInfo.isMobile} theme={theme}>
            <button
              type="button"
              aria-pressed={!flatMode}
              onClick={() => {
                setShowSettings(false);
                toggleFlatMode();
              }}
            >
              {flatMode ? "Turn on 3D effects" : "Turn off 3D effects"}
            </button>
          </SettingsMenu>
        )}

        <VoiceAvatar
          state={assistantState}
          $disabled={isDisabled}
          $compact={compact}
          isMobile={deviceInfo.isMobile}
          motionReduce={motionReduce}
          flatMode={flatMode}
          voiceIntensity={voiceIntensity}
          type="button"
          data-primary-control=""
          aria-label={avatarLabel}
          title={
            isDisabled
              ? deviceInfo.isMobile
                ? "Tap to enable voice chat!"
                : "Click to enable voice chat!"
              : avatarLabel
          }
          onClick={async () => {
            if (isDisabled) {
              if (!hasPermission) {
                await requestMicrophonePermission();
              }
              return;
            }

            if (assistantState === "idle") {
              // Initialize speech synthesis context (required for some browsers)
              if (!window.speechSynthesis.speaking) {
                const testUtterance = new SpeechSynthesisUtterance("");
                testUtterance.volume = 0;
                window.speechSynthesis.speak(testUtterance);
                window.speechSynthesis.cancel();
              }

              // First interaction: speak introduction then listen
              if (isFirstInteraction) {
                speakIntroduction();
              } else {
                // Subsequent interactions: directly start listening
                startListening();
              }
            } else {
              stopAll();
            }
          }}
        >
          <AvatarGlyph
            aria-hidden="true"
            state={assistantState}
            disabled={isDisabled}
            isMobile={deviceInfo.isMobile}
          />
        </VoiceAvatar>

        <VoiceStatus
          $compact={compact}
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
        >
          {/* Sighted users see the orb change colour; this is the equivalent
              cue for a screen reader. */}
          <div className="visually-hidden" aria-live="polite">
            {avatarLabel}
          </div>
          <div className="status-title" aria-hidden="true">
            {statusText.title}
          </div>
          <div className="status-subtitle" aria-hidden="true">
            {statusText.subtitle}
          </div>
        </VoiceStatus>

        {!hasPermission && assistantState === "idle" && (
          <EnableMicButton
            type="button"
            isMobile={deviceInfo.isMobile}
            theme={theme}
            disabled={connectionStatus === "connecting"}
            onClick={requestMicrophonePermission}
          >
            <MicrophoneIcon size={15} color="currentColor" />
            {connectionStatus === "connecting"
              ? "Waiting for permission…"
              : "Enable microphone"}
          </EnableMicButton>
        )}

        {(assistantState === "listening" || assistantState === "speaking") && (
          <VoiceWaves
            state={assistantState}
            isMobile={deviceInfo.isMobile}
            motionReduce={motionReduce}
            flatMode={flatMode}
            live={isMetering && assistantState === "listening"}
            aria-hidden="true"
          >
            {(() => {
              const barCount = deviceInfo.isMobile ? 5 : 7;
              const live = isMetering && assistantState === "listening";
              const maxRise = deviceInfo.isMobile ? 14 : 24;
              return [...Array(barCount)].map((_, i) => {
                // Arch profile so the row reads as a waveform, not a wall
                const arch = Math.sin(((i + 1) / (barCount + 1)) * Math.PI);
                const weight = 0.45 + 0.55 * arch;
                return (
                  <div
                    key={i}
                    className="wave-bar"
                    style={
                      live
                        ? {
                            height: `${
                              4 + voiceIntensity * maxRise * weight
                            }px`,
                            opacity: 0.55 + voiceIntensity * 0.45,
                          }
                        : undefined
                    }
                  />
                );
              });
            })()}
          </VoiceWaves>
        )}

        <PanelBody isMobile={deviceInfo.isMobile}>
        {(interimTranscript ||
          transcriptEntries.length > 0 ||
          assistantState === "thinking") && (
          <TranscriptPanel
            ref={transcriptRef}
            isMobile={deviceInfo.isMobile}
            role="log"
            aria-live="polite"
            aria-label="Conversation transcript"
          >
            {transcriptEntries.map((entry, i) => (
              <div className="transcript-row" key={entry.id}>
                <span
                  className={`transcript-tag ${
                    entry.role === "you" ? "tag-you" : "tag-ai"
                  }`}
                >
                  {entry.role === "you" ? "You" : "AI"}
                </span>
                <span className="transcript-text">
                  {entry.role === "ai" &&
                  !entry.restored &&
                  !entry.streamed &&
                  i === transcriptEntries.length - 1 ? (
                    <TypewriterText
                      text={entry.text}
                      instant={motionReduce}
                      onTick={scrollTranscriptToEnd}
                    />
                  ) : (
                    entry.text
                  )}
                </span>
              </div>
            ))}
            {!!interimTranscript && (
              // Excluded from the log: interim results change on nearly every
              // frame and would flood a screen reader. The status line above
              // already announces that we're listening.
              <div className="transcript-row" key="interim" aria-hidden="true">
                <span className="transcript-tag tag-you">You</span>
                <span className="transcript-text interim">
                  {interimTranscript}
                  <span className="type-caret" />
                </span>
              </div>
            )}
            {assistantState === "thinking" && (
              <div className="transcript-row" key="thinking" aria-hidden="true">
                <span className="transcript-tag tag-ai">AI</span>
                <span className="transcript-text thinking-dots">
                  <span />
                  <span />
                  <span />
                </span>
              </div>
            )}
          </TranscriptPanel>
        )}

        {answerLinks.length > 0 && assistantState !== "thinking" && (
          <FollowUpRow
            isMobile={deviceInfo.isMobile}
            role="navigation"
            aria-label="Related links"
          >
            {answerLinks.map((l) =>
              l.external ? (
                <AnswerLink
                  key={l.href}
                  as="a"
                  href={l.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  isMobile={deviceInfo.isMobile}
                  theme={theme}
                >
                  {l.label} <span aria-hidden="true">↗</span>
                </AnswerLink>
              ) : (
                <AnswerLink
                  key={l.href}
                  type="button"
                  isMobile={deviceInfo.isMobile}
                  theme={theme}
                  onClick={() => history.push(l.href)}
                >
                  {l.label} <span aria-hidden="true">→</span>
                </AnswerLink>
              )
            )}
          </FollowUpRow>
        )}

        {transcriptEntries.length > 0 && (
          <TranscriptTools>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={copyTranscript}
              aria-label={
                copiedTranscript
                  ? "Transcript copied to clipboard"
                  : "Copy transcript to clipboard"
              }
            >
              {copiedTranscript ? "Copied" : "Copy"}
            </TranscriptToolButton>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={emailTranscript}
              aria-label="Email this transcript to Laxman"
            >
              Email it
            </TranscriptToolButton>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={clearTranscript}
              aria-label="Clear the conversation"
            >
              Clear
            </TranscriptToolButton>
          </TranscriptTools>
        )}

        {showStarters && (
          <FollowUpRow isMobile={deviceInfo.isMobile} data-starters="">
            {starterQuestions.map((q) => (
              <FollowUpChip
                key={q}
                type="button"
                isMobile={deviceInfo.isMobile}
                theme={theme}
                onClick={() => submitText(q)}
              >
                {q}
              </FollowUpChip>
            ))}
          </FollowUpRow>
        )}

        {followUps.length > 0 && assistantState === "idle" && (
          <FollowUpRow isMobile={deviceInfo.isMobile}>
            {followUps.map((f, i) => (
              <FollowUpChip
                key={`${f.action || "f"}-${i}`}
                type="button"
                isMobile={deviceInfo.isMobile}
                theme={theme}
                onClick={() => submitText(f.question)}
              >
                {f.question}
              </FollowUpChip>
            ))}
          </FollowUpRow>
        )}

        {showTextInput && (
          <TextInputRow
            isMobile={deviceInfo.isMobile}
            theme={theme}
            onSubmit={(e) => {
              e.preventDefault();
              submitText(textInput);
            }}
          >
            <TextInputField
              ref={textInputRef}
              isMobile={deviceInfo.isMobile}
              theme={theme}
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              placeholder="Type a question about Laxman…"
              aria-label="Type a question about Laxman"
              autoComplete="off"
              disabled={assistantState === "thinking"}
            />
            <TextSendButton
              type="submit"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              disabled={!textInput.trim() || assistantState === "thinking"}
              aria-label="Send question"
              title="Send"
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill="none"
                aria-hidden="true"
              >
                <path
                  d="M4 12h15M13 6l6 6-6 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </TextSendButton>
          </TextInputRow>
        )}

        </PanelBody>

        <VoiceControls
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          data-controls=""
        >
          <ButtonRow isMobile={deviceInfo.isMobile} flatMode={flatMode}>
            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={assistantState === "idle" ? startListening : stopAll}
                disabled={isDisabled}
                active={assistantState !== "idle"}
                buttonType="mic"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-label={
                  assistantState === "idle"
                    ? "Ask one question"
                    : "Stop the assistant"
                }
                title={
                  assistantState === "idle"
                    ? "Ask one question"
                    : "Stop current action"
                }
              >
                <div className="icon-wrapper">
                  <ButtonIcon
                    type={assistantState === "idle" ? "mic" : "stop"}
                  />
                </div>
              </VoiceButton>
              <ButtonLabel
                disabled={isDisabled}
                isMobile={deviceInfo.isMobile}
                theme={theme}
              >
                {deviceInfo.isMobile ? "Ask once" : "Ask\nonce"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                active={isAutoMode}
                onClick={toggleAutoMode}
                disabled={isDisabled}
                buttonType="auto"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-pressed={isAutoMode}
                aria-label="Continuous conversation mode"
                title="Toggle continuous conversation mode"
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="auto" />
                </div>
              </VoiceButton>
              <ButtonLabel disabled={isDisabled} isMobile={deviceInfo.isMobile}>
                {deviceInfo.isMobile ? "Hands-free" : "Hands-\nfree"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={testTTS}
                disabled={!("speechSynthesis" in window)}
                buttonType="test"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-label="Test voice output"
                title="Test voice output"
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="test" />
                </div>
              </VoiceButton>
              <ButtonLabel
                disabled={!("speechSynthesis" in window)}
                isMobile={deviceInfo.isMobile}
              >
                {deviceInfo.isMobile ? "Test voice" : "Test\nvoice"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={() => setShowTextInput((v) => !v)}
                active={showTextInput}
                buttonType="type"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                title="Type your question instead"
                aria-label="Type your question instead"
                aria-pressed={showTextInput}
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="keyboard" />
                </div>
              </VoiceButton>
              <ButtonLabel isMobile={deviceInfo.isMobile} theme={theme}>
                {deviceInfo.isMobile ? "Type" : "Type\ninstead"}
              </ButtonLabel>
            </div>
          </ButtonRow>
        </VoiceControls>

        <HelpHint
          show={
            showHelp &&
            !showStarters &&
            assistantState === "idle" &&
            connectionStatus === "connected"
          }
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          aria-hidden="true"
        >
          {deviceInfo.isMobile
            ? "Ask about projects, experience or contact"
            : "Ask about projects, experience, or how to reach Laxman"}
        </HelpHint>
      </VoiceContainer>
    </>
  );
};

// Main Export with Enhanced Liquid Glass

const LiquidGlassSiri = ({ onClose, theme }) => {
  return <VoiceAssistant onClose={onClose} theme={theme} />;
};

export default LiquidGlassSiri;
